\set ON_ERROR_STOP on
insert into users values('00000000-0000-4000-8000-000000000007');
insert into tenant_memberships values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000007','active','member');
insert into assessment_capability_grants(tenant_id,user_id,capability,granted_by) values
 ('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000007','results.release','00000000-0000-4000-8000-000000000001');
insert into tenant_memberships values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','active','member');
insert into assessment_capability_grants(tenant_id,user_id,capability,granted_by) values
 ('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','results.read','00000000-0000-4000-8000-000000000001');
do $$ declare tenant uuid:='10000000-0000-4000-8000-000000000001';owner uuid:='00000000-0000-4000-8000-000000000001';reviewer uuid:='00000000-0000-4000-8000-000000000002';candidate uuid:='00000000-0000-4000-8000-000000000003';marker1 uuid:='00000000-0000-4000-8000-000000000005';marker2 uuid:='00000000-0000-4000-8000-000000000006';
 result jsonb;bank uuid;rubric uuid;objective uuid;essay uuid;definition jsonb;assessment uuid;version_id uuid;win uuid;reg uuid;form jsonb;attempt uuid;ticket jsonb;bundle jsonb;report jsonb;run1 uuid;run2 uuid;task uuid;summary jsonb;context jsonb;decision_hash text;mark1 jsonb;release_id uuid;
begin
 result:=assessment_command(owner,tenant,'grade-bank-create','bank.create','{"title":"Grading bank"}');bank:=(result->>'id')::uuid;
 result:=assessment_command(owner,tenant,'grade-rubric-create','rubric.create','{"title":"Writing rubric","criteria":[{"id":"a","title":"Accuracy","max_score":9,"descriptor":"Accuracy criteria"},{"id":"b","title":"Content","max_score":9,"descriptor":"Content criteria"}]}');rubric:=(result->>'id')::uuid;
 begin update assessment_rubrics set criteria='[]' where id=rubric;raise exception 'Rubric mutation accepted';exception when check_violation then null;end;
 result:=assessment_command(owner,tenant,'grade-objective-create','item.create',jsonb_build_object('bank_id',bank,'item','{"schema_version":"assessment.item.v1","type":"single_choice","prompt":"2 + 2?","locale":"en","max_score":1,"tags":[],"options":[{"id":"a","text":"4"},{"id":"b","text":"5"}]}'::jsonb,'key','{"correct":"a"}'::jsonb));objective:=(result->>'id')::uuid;
 result:=assessment_command(owner,tenant,'grade-essay-create','item.create',jsonb_build_object('bank_id',bank,'item',jsonb_build_object('schema_version','assessment.item.v1','type','essay','prompt','Explain your reasoning','locale','en','max_score',9,'tags','[]'::jsonb,'rubric_id',rubric),'key','{}'::jsonb));essay:=(result->>'id')::uuid;
 perform assessment_command(owner,tenant,'grade-objective-review','item.submit',jsonb_build_object('id',objective));perform assessment_command(reviewer,tenant,'grade-objective-approve','item.approve',jsonb_build_object('id',objective));
 perform assessment_command(owner,tenant,'grade-essay-review','item.submit',jsonb_build_object('id',essay));perform assessment_command(reviewer,tenant,'grade-essay-approve','item.approve',jsonb_build_object('id',essay));
 definition:=jsonb_build_object('schema_version','assessment.definition.v1','title','Mixed assessment','locale','en','duration_seconds',600,'shuffle_items',false,'shuffle_options',false,'sections',jsonb_build_array(jsonb_build_object('id','20000000-0000-4000-8000-000000000009','title','Mixed','item_version_ids',jsonb_build_array(objective,essay),'draw_count',2)));
 result:=assessment_command(owner,tenant,'grade-assessment-create','assessment.create',jsonb_build_object('definition',definition));assessment:=(result->>'id')::uuid;
 result:=assessment_command(owner,tenant,'grade-publication','assessment.publish',jsonb_build_object('id',assessment,'revision',1));version_id:=(result->>'id')::uuid;
 result:=assessment_command(owner,tenant,'grade-window-create','window.create',jsonb_build_object('assessment_version_id',version_id,'title','Grading sitting','opens_at',clock_timestamp()-interval '1 hour','closes_at',clock_timestamp()+interval '2 hours'));win:=(result->>'id')::uuid;
 perform assessment_grading_command(owner,tenant,'grade-policy-config','policy.configure',jsonb_build_object('window_id',win,'marker_count',2,'tolerance_percent',0));
 result:=assessment_command(owner,tenant,'grade-registration','registration.create',jsonb_build_object('window_id',win,'candidate_id',candidate));reg:=(result->>'id')::uuid;
 form:=jsonb_build_object('schema_version','assessment.manifest.v1','assessment_version_id',version_id,'duration_seconds',600,'sections',jsonb_build_array(jsonb_build_object('id','20000000-0000-4000-8000-000000000009','items',jsonb_build_array(jsonb_build_object('item_version_id',objective),jsonb_build_object('item_version_id',essay)))));
 result:=assessment_command(candidate,tenant,'grade-attempt-start','attempt.start',jsonb_build_object('registration_id',reg,'manifest',form,'manifest_hash',repeat('b',64)));attempt:=(result->>'id')::uuid;
 begin perform assessment_grading_command(owner,tenant,'grade-policy-change','policy.configure',jsonb_build_object('window_id',win,'marker_count',1,'tolerance_percent',0));raise exception 'Started-exam grading policy changed';exception when check_violation then null;end;
 begin update assessment_attempts set grading_policy_snapshot='{"marker_count":1}' where id=attempt;raise exception 'Attempt grading policy mutated';exception when check_violation then null;end;
 perform pg_temp.assessment_command(candidate,tenant,'grade-answer-old','response.append',jsonb_build_object('attempt_id',attempt,'sequence',1,'item_version_id',objective,'response','b','payload_hash','old'));
 perform pg_temp.assessment_command(candidate,tenant,'grade-answer-latest','response.append',jsonb_build_object('attempt_id',attempt,'sequence',2,'item_version_id',objective,'response','a','payload_hash','latest'));
 perform pg_temp.assessment_command(candidate,tenant,'grade-answer-essay','response.append',jsonb_build_object('attempt_id',attempt,'sequence',3,'item_version_id',essay,'response','Candidate explanation','payload_hash','essay'));
 perform pg_temp.assessment_command(candidate,tenant,'grade-finalize','attempt.submit',jsonb_build_object('attempt_id',attempt));
 if not exists(select 1 from assessment_grading_jobs where attempt_id=attempt and generation=1) then raise exception 'Finalization did not transactionally enqueue grading';end if;
 select value into ticket from jsonb_array_elements(assessment_grading_claim(100)) where value->>'attempt_id'=attempt::text;
 bundle:=assessment_grading_bundle(tenant,attempt,1,(ticket->>'lease_token')::uuid);
 if not exists(select 1 from jsonb_array_elements(bundle->'items') where value->>'item_version_id'=objective::text and value->>'response'='a') then raise exception 'Grader did not select the latest canonical response';end if;
 report:=jsonb_build_object('scorer_version','assessment.scorer.v1','input_hash',bundle->>'input_hash','scores',jsonb_build_array(jsonb_build_object('item_version_id',objective,'score',1,'max_score',1,'status','scored'),jsonb_build_object('item_version_id',essay,'score',null,'max_score',9,'status','needs_human')));
 begin perform assessment_grading_commit(tenant,attempt,1,(ticket->>'lease_token')::uuid,jsonb_set(report,'{input_hash}',to_jsonb(repeat('a',64))));raise exception 'Stale grading input accepted';exception when check_violation then null;end;
 result:=assessment_grading_commit(tenant,attempt,1,(ticket->>'lease_token')::uuid,report);run1:=(result->>'id')::uuid;
 if assessment_grading_commit(tenant,attempt,1,(ticket->>'lease_token')::uuid,report)<>result then raise exception 'Commit replay changed run';end if;
 select id into task from assessment_grading_tasks where run_id=run1;
 context:=assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'access');
 if not (context->>'can_release')::boolean or (context->>'can_mark')::boolean or (context->>'can_moderate')::boolean or (context->>'can_read_banks')::boolean then raise exception 'Release-only workspace grants unrelated features';end if;
 if exists(select 1 from jsonb_array_elements(assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'runs')) where value->>'id'=run1::text) then raise exception 'Release-only staff saw unapproved grade';end if;
 begin perform assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'run',run1);raise exception 'Release-only staff opened unapproved grade';exception when insufficient_privilege then null;end;
 begin perform assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'worklist');raise exception 'Release-only staff enumerated marking tasks';exception when insufficient_privilege then null;end;
 begin perform assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'markers',task);raise exception 'Release-only staff enumerated marker directory';exception when insufficient_privilege then null;end;
 begin perform assessment_grading_command(marker1,tenant,'grade-proctor-bypass','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":6,"b":6}'::jsonb,'rationale','First mark'));raise exception 'Proctor-only role can mark';exception when insufficient_privilege then null;end;
 insert into assessment_capability_grants(tenant_id,user_id,capability,granted_by) values(tenant,marker1,'grades.mark',owner),(tenant,marker2,'grades.mark',owner),(tenant,marker1,'grades.moderate',owner);
 insert into assessment_capability_grants(tenant_id,user_id,capability,granted_by) values(tenant,candidate,'grades.mark',owner);
 context:=assessment_grading_read(owner,tenant,'markers',task);
 if exists(select 1 from jsonb_array_elements(context) where value->>'id'=candidate::text) or not exists(select 1 from jsonb_array_elements(context) where value->>'id'=marker2::text) then raise exception 'Marker directory did not enforce candidate exclusion and marking authority';end if;
 update tenant_memberships set status='inactive' where tenant_id=tenant and user_id=marker2;
 if exists(select 1 from jsonb_array_elements(assessment_grading_read(owner,tenant,'markers',task)) where value->>'id'=marker2::text) then raise exception 'Inactive marker remained selectable';end if;
 update tenant_memberships set status='active' where tenant_id=tenant and user_id=marker2;
 perform assessment_grading_command(owner,tenant,'grade-assign-one','marker.assign',jsonb_build_object('task_id',task,'marker_id',marker1,'slot',1));perform assessment_grading_command(owner,tenant,'grade-assign-two','marker.assign',jsonb_build_object('task_id',task,'marker_id',marker2,'slot',2));
 begin perform assessment_grading_command(owner,tenant,'grade-assign-candidate','marker.assign',jsonb_build_object('task_id',task,'marker_id',candidate,'slot',1));raise exception 'Candidate assigned own marking';exception when insufficient_privilege then null;end;
 begin perform assessment_grading_command(marker1,tenant,'grade-mark-invalid','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":10,"b":6}'::jsonb,'rationale','Invalid'));raise exception 'Out-of-range criterion accepted';exception when check_violation then null;end;
 mark1:=assessment_grading_command(marker1,tenant,'grade-mark-one','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":6,"b":6}'::jsonb,'rationale','First mark'));
 if (mark1->>'score')::numeric<>6 then raise exception 'Rubric normalization incorrect';end if;
 if assessment_grading_command(marker1,tenant,'grade-mark-one','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":6,"b":6}'::jsonb,'rationale','First mark'))<>mark1 then raise exception 'Human mark duplicated on retry';end if;
 context:=assessment_grading_read(marker1,tenant,'task',task);if context?'marks' or context?'review_hash' or context?'candidate_id' or context?'key' then raise exception 'Blind marker context leaked peer marks, keys or identity';end if;
 begin perform assessment_grading_read(marker1,tenant,'run',run1);raise exception 'Assigned marker can inspect aggregate peer scores';exception when insufficient_privilege then null;end;
 perform assessment_grading_command(marker2,tenant,'grade-mark-two','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":9,"b":9}'::jsonb,'rationale','Second mark'));
 context:=assessment_grading_read(reviewer,tenant,'task',task);decision_hash:=context->>'review_hash';if context->>'status'<>'needs_moderation' then raise exception 'Disagreement was silently averaged';end if;
 begin perform assessment_grading_command(marker1,tenant,'grade-self-adjudicate','mark.adjudicate',jsonb_build_object('task_id',task,'score',7,'review_hash',decision_hash,'rationale','Self'));raise exception 'Marker adjudicated own disagreement';exception when insufficient_privilege then null;end;
 perform assessment_grading_command(reviewer,tenant,'grade-adjudication-one','mark.adjudicate',jsonb_build_object('task_id',task,'score',7,'review_hash',decision_hash,'rationale','Independent decision'));
 summary:=assessment_grading_read(owner,tenant,'run',run1);
 begin perform assessment_grading_command(reviewer,tenant,'grade-self-approval','grade.approve',jsonb_build_object('run_id',run1,'review_hash',summary->>'review_hash'));raise exception 'Adjudicator approved own consequential decision';exception when insufficient_privilege then null;end;
 perform assessment_grading_command(marker1,tenant,'grade-mark-one-revision','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":7,"b":7}'::jsonb,'rationale','Corrected first mark'));
 begin perform assessment_grading_command(owner,tenant,'grade-stale-approval','grade.approve',jsonb_build_object('run_id',run1,'review_hash',summary->>'review_hash'));raise exception 'Stale marks remained approved';exception when unique_violation then null;end;
 context:=assessment_grading_read(reviewer,tenant,'task',task);if context->>'status'<>'needs_moderation' then raise exception 'Old adjudication survived changed marks';end if;
 perform assessment_grading_command(reviewer,tenant,'grade-adjudication-two','mark.adjudicate',jsonb_build_object('task_id',task,'score',8,'review_hash',context->>'review_hash','rationale','Re-reviewed revised marks'));
 summary:=assessment_grading_read(owner,tenant,'run',run1);if (summary->>'total')::numeric<>9 then raise exception 'Canonical objective plus human total incorrect';end if;
 perform assessment_grading_command(owner,tenant,'grade-final-approval','grade.approve',jsonb_build_object('run_id',run1,'review_hash',summary->>'review_hash'));
 context:=assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'run',run1);
 if not (context->>'can_release')::boolean or (context->>'can_approve')::boolean or (context->>'can_regrade')::boolean then raise exception 'Release-only approved grade permissions incorrect';end if;
 if not exists(select 1 from jsonb_array_elements(assessment_grading_read('00000000-0000-4000-8000-000000000007',tenant,'runs')) where value->>'id'=run1::text) then raise exception 'Approved grade missing from release queue';end if;
 begin perform assessment_grading_command(marker1,tenant,'grade-post-approval','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":8,"b":8}'::jsonb,'rationale','Too late'));raise exception 'Approved grade changed in place';exception when check_violation then null;end;
 result:=assessment_grading_command(owner,tenant,'grade-embargo-release','grade.release',jsonb_build_object('run_id',run1,'release_at',clock_timestamp()+interval '1 hour'));release_id:=(result->>'id')::uuid;
 if jsonb_array_length(assessment_grading_read(candidate,tenant,'results'))<>0 then raise exception 'Embargoed result leaked';end if;
 begin update assessment_grading_releases set release_at=clock_timestamp() where id=release_id;raise exception 'Release snapshot modified';exception when check_violation then null;end;
 perform assessment_grading_command(owner,tenant,'grade-regrade-request','grade.regrade',jsonb_build_object('run_id',run1,'reason','Review request'));
 select value into ticket from jsonb_array_elements(assessment_grading_claim(100)) where value->>'attempt_id'=attempt::text and value->>'generation'='2';bundle:=assessment_grading_bundle(tenant,attempt,2,(ticket->>'lease_token')::uuid);report:=jsonb_set(report,'{input_hash}',to_jsonb(bundle->>'input_hash'));
 result:=assessment_grading_commit(tenant,attempt,2,(ticket->>'lease_token')::uuid,report);run2:=(result->>'id')::uuid;select id into task from assessment_grading_tasks where run_id=run2;
 perform assessment_grading_command(owner,tenant,'grade-assign-new-one','marker.assign',jsonb_build_object('task_id',task,'marker_id',marker1,'slot',1));perform assessment_grading_command(owner,tenant,'grade-assign-new-two','marker.assign',jsonb_build_object('task_id',task,'marker_id',marker2,'slot',2));
 perform assessment_grading_command(marker1,tenant,'grade-new-mark-one','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":7,"b":7}'::jsonb,'rationale','New generation first mark'));perform assessment_grading_command(marker2,tenant,'grade-new-mark-two','mark.submit',jsonb_build_object('task_id',task,'criteria','{"a":7,"b":7}'::jsonb,'rationale','New generation second mark'));
 summary:=assessment_grading_read(owner,tenant,'run',run2);perform assessment_grading_command(owner,tenant,'grade-new-approve','grade.approve',jsonb_build_object('run_id',run2,'review_hash',summary->>'review_hash'));perform assessment_grading_command(owner,tenant,'grade-new-release','grade.release',jsonb_build_object('run_id',run2));
 result:=assessment_grading_read(candidate,tenant,'results');if jsonb_array_length(result)<>1 or result->0->>'generation'<>'2' or (result->0->>'total')::numeric<>8 then raise exception 'Candidate did not receive latest eligible released generation';end if;
 if (select status from assessment_grading_runs where id=run1)<>'released' or (select count(*) from assessment_grading_marks m join assessment_grading_assignments a on a.id=m.assignment_id join assessment_grading_tasks t on t.id=a.task_id where t.run_id=run1)<>3 then raise exception 'Regrading destroyed original history';end if;
 if (select count(*) from domain_event_outbox where event_type='assessment.result.released' and aggregate_id=attempt)<>2 then raise exception 'Result release events duplicated or lost';end if;
end; $$;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
do $$ begin
 if exists(select 1 from assessment_score_revisions v join assessment_attempts a on a.id=v.attempt_id where a.candidate_id=auth.uid()) then raise exception 'Candidate bypassed result release through raw score RLS';end if;
 begin perform * from assessment_grading_marks;raise exception 'Raw human marks readable';exception when insufficient_privilege then null;end;
 begin perform assessment_grading_claim(1);raise exception 'Candidate can lease grader jobs';exception when insufficient_privilege then null;end;
 begin perform assessment_grading_input(gen_random_uuid(),gen_random_uuid(),1);raise exception 'Private answer keys available through grading input';exception when insufficient_privilege then null;end;
end; $$;
reset role;
